# Process each normalized crew change case
output = []

for item in _items:

    case = item["json"].copy()

    risk_score = 0
    risk_signals = []


    # --------------------------------------------------
    # 1. CONNECTION TIME RISK
    # --------------------------------------------------

    connection_minutes = case.get("shortest_connection_minutes")

    if connection_minutes is not None:

        if connection_minutes < 45:
            risk_score += 30
            risk_signals.append(
                "Critical: Very short flight connection"
            )

        elif connection_minutes < 60:
            risk_score += 20
            risk_signals.append(
                "High risk: Tight flight connection"
            )

        elif connection_minutes < 90:
            risk_score += 10
            risk_signals.append(
                "Moderate risk: Limited connection time"
            )


    # --------------------------------------------------
    # 2. DESTINATION AIRPORT DELAY RISK
    # --------------------------------------------------

    delay_risk = case.get("destination_delay_risk_public")

    if delay_risk == "High":
        risk_score += 20
        risk_signals.append(
            "High destination airport delay risk"
        )

    elif delay_risk == "Medium":
        risk_score += 10
        risk_signals.append(
            "Medium destination airport delay risk"
        )


    # --------------------------------------------------
    # 3. PORT TRANSFER RISK
    # --------------------------------------------------

    transfer_minutes = case.get("port_transfer_minutes")

    if transfer_minutes is not None:

        if transfer_minutes >= 120:
            risk_score += 15
            risk_signals.append(
                "Long airport-to-port transfer"
            )

        elif transfer_minutes >= 90:
            risk_score += 10
            risk_signals.append(
                "Extended airport-to-port transfer"
            )


    # --------------------------------------------------
    # 4. VESSEL ETA CONFIDENCE
    # --------------------------------------------------

    eta_confidence = case.get("vessel_eta_confidence")

    if eta_confidence == "Low":
        risk_score += 15
        risk_signals.append(
            "Low confidence in vessel ETA"
        )

    elif eta_confidence == "Medium":
        risk_score += 8
        risk_signals.append(
            "Medium confidence in vessel ETA"
        )


    # --------------------------------------------------
    # 5. VISA STATUS
    # --------------------------------------------------

    visa_status = case.get("visa_status")

    if visa_status == "Potential issue":
        risk_score += 20
        risk_signals.append(
            "Potential visa issue"
        )

    elif visa_status == "Manual specialist check":
        risk_score += 15
        risk_signals.append(
            "Visa requires manual specialist review"
        )

    elif visa_status == "Pending verification":
        risk_score += 10
        risk_signals.append(
            "Visa verification pending"
        )


    # --------------------------------------------------
    # 6. DOCUMENT VERIFICATION
    # --------------------------------------------------

    documents_verified = case.get("documents_verified")

    if documents_verified is not True:
        risk_score += 10
        risk_signals.append(
            "Crew documents not verified"
        )


    # --------------------------------------------------
    # 7. PORT AGENT CONFIRMATION
    # --------------------------------------------------

    port_agent_confirmed = case.get(
        "port_agent_confirmed"
    )

    if port_agent_confirmed is not True:
        risk_score += 10
        risk_signals.append(
            "Port agent confirmation missing"
        )


    # --------------------------------------------------
    # 8. TICKET STATUS
    # --------------------------------------------------

    ticket_status = case.get("ticket_status")

    if ticket_status == "Not requested":
        risk_score += 15
        risk_signals.append(
            "Flight ticket not yet requested"
        )

    elif ticket_status == "Quoted":
        risk_score += 10
        risk_signals.append(
            "Flight ticket quotation pending"
        )

    elif ticket_status == "Reserved":
        risk_score += 5
        risk_signals.append(
            "Flight ticket reserved but not issued"
        )


    # --------------------------------------------------
    # DETERMINE OVERALL RISK LEVEL
    # --------------------------------------------------

    if risk_score >= 50:
        risk_level = "Critical"

    elif risk_score >= 30:
        risk_level = "High"

    elif risk_score >= 15:
        risk_level = "Medium"

    else:
        risk_level = "Low"


    # --------------------------------------------------
    # RECOMMENDED ATTENTION
    # --------------------------------------------------

    if risk_level in ["Critical", "High"]:
        recommended_attention = (
            "Immediate operational review required"
        )

    elif risk_level == "Medium":
        recommended_attention = (
            "Monitor and review before execution"
        )

    else:
        recommended_attention = (
            "No immediate action required"
        )


    # --------------------------------------------------
    # ADD RESULTS TO CASE
    # --------------------------------------------------

    case["initial_risk_score"] = risk_score
    case["initial_risk_level"] = risk_level
    case["risk_signals"] = risk_signals
    case["recommended_attention"] = recommended_attention


    output.append({
        "json": case
    })


return output

# Create a list for cleaned port records
output = []

# Loop through incoming items
for incoming_item in _items:

    # Get the Airtable fields
    fields = incoming_item["json"].get("fields", {})

    # Keep only operationally useful port information
    clean_port = {
        "port_name": fields.get("port_name"),
        "city": fields.get("city"),
        "country_code": fields.get("country_code"),
        "latitude": fields.get("latitude"),
        "longitude": fields.get("longitude")
    }

    # Add the cleaned joining port
    output.append({
        "json": {
            "joining_port": clean_port
        }
    })

# Return cleaned port records
return output

